export const EXTRA_SCRIPT="(() => {
"use strict";
const $=id=>document.getElementById(id);
let profile=null, lastShown=null, cameraStream=null, frameId=null, lastFrame=0, jsqrLoading=null, nativeDetector=null, cameraBusy=false, scanCount=0;
const locale={
es:{
qrTitle:"Mi tarjeta QR",qrHelp:"Este QR contiene únicamente tu código de socio. No registra visitas por sí solo.",qrZoom:"Ampliar QR",qrClose:"Cerrar QR",qrError:"No se ha podido generar el QR",
