};
const t=()=>locale[document.documentElement.lang==="fr"?"fr":"es"];
function text(id,value){const item=$(id);if(item)item.textContent=String(value??"");}
function translate(){const d=t();for(const id of ["qrTitle","qrHelp","qrZoom","qrClose","activityTitle","doorTitle","doorHelp","doorScanHelp","doorLabel","doorCheck","doorCamera","doorStop","doorReadOnly","adminTitle","adminButton","adminHelp"])text(id,d[id]);text("doorPhotoLabel",d.doorPhoto);}
async function json(path){const res=await fetch(path,{credentials:"same-origin",cache:"no-store",headers:{Accept:"application/json"}});if(!res.ok)throw new Error("HTTP "+res.status);return res.json();}
async function loadActivity(){
 const output=$("activityItems");
 output.replaceChildren();
 try{
  const result=await json("/v1/me/activity");
  const records=Array.isArray(result.items)?result.items.slice(0,8):[];
  if(!records.length){
   const li=document.createElement("li");li.textContent=t().activityEmpty;
   output.replaceChildren(li);return;
  }
  const nodes=[];
  for(const item of records){
   const li=document.createElement("li");
   const delta=Number(item.delta);
   const value=Number.isFinite(delta)?(" ("+(delta>0?"+":"")+delta+")"):"";
   const desc=String(item.detail||item.type||"").slice(0,220);
   li.textContent=desc+value;nodes.push(li);
  }
  output.replaceChildren(...nodes);
 }catch(_){
  const li=document.createElement("li");li.textContent=t().activityError;
  output.replaceChildren(li);
 }
}
async function refresh(){
 try{
 const data=await json("/v1/auth/me");profile=data.authenticated?data.profile:null;
 const isStaff=!!profile&&["puerta","admin"].includes(profile.role),isAdmin=!!profile&&profile.role==="admin";
 $("qrPanel").hidden=!profile;$("activityPanel").hidden=!profile;$("doorPanel").hidden=!isStaff;$("adminPanel").hidden=!isAdmin;
 if(!isStaff)stopCamera();
 if(profile){
   try{if(!globalThis.BellaQR||!/^MBR-[A-Z0-9-]{5,80}$/i.test(profile.member_code))throw Error("Invalid QR");globalThis.BellaQR.render($("qrImage"),profile.member_code,{label:"Tarjeta QR Bellaquitas"});globalThis.BellaQR.render($("qrLarge"),profile.member_code,{label:"Tarjeta QR ampliada"});text("qrError","");}
   catch(_){text("qrError",t().qrError);$("qrImage").replaceChildren();$("qrLarge").replaceChildren();}
   await loadActivity();
 }else{$("qrOverlay").hidden=true;$("qrImage").replaceChildren();$("qrLarge").replaceChildren();$("activityItems").replaceChildren();}
 }catch(_){profile=null;for(const id of ["qrPanel","activityPanel","doorPanel","adminPanel","qrOverlay"])$(id).hidden=true;stopCamera();}
}
const validMemberCode=code=>/^MBR-[A-Z0-9-]{5,80}$/.test(code);
async function lookupDoorCode(code){
 text("doorStatus",t().doorLoading);
 try{
  const response=await json("/v1/door/members");
  const found=(response.items||[]).find(m=>String(m.member_code||"").toUpperCase()===code);
  text("doorStatus",found?t().doorFound+": "+found.name+" · "+found.member_code:t().doorUnknown);
 }catch(_){text("doorStatus",t().doorUnknown);}
}
async function doorLookup(event){
 event.preventDefault();
 if(!profile||!["puerta","admin"].includes(profile.role))return;
 const code=$("doorCode").value.trim().toUpperCase();
 if(!validMemberCode(code)){text("doorStatus",t().doorInvalid);return;}
 await lookupDoorCode(code);
}
async function loadJsQr(){
 if(typeof globalThis.jsQR==="function")return;
 if(jsqrLoading)return jsqrLoading;
 jsqrLoading=new Promise((resolve,reject)=>{
  const script=document.createElement("script");
  script.src="/preview/jsqr-local.js";
  script.onload=()=>typeof globalThis.jsQR==="function"?resolve():reject(Error("jsQR"));
  script.onerror=()=>reject(Error("jsQR"));
  document.head.append(script);
 });
 try{await jsqrLoading;}catch(error){jsqrLoading=null;throw error;}
}
function getNativeDetector(){
 if(nativeDetector!==null)return nativeDetector||null;
 if(typeof globalThis.BarcodeDetector!=="function"){nativeDetector=false;return null;}
 try{nativeDetector=new globalThis.BarcodeDetector({formats:["qr_code"]});}
 catch(_){nativeDetector=false;}
 return nativeDetector||null;
}
function useReadResult(raw){
 const value=String(raw||"").trim().toUpperCase();
 if(!value)return false;
 if(!validMemberCode(value)){
  text("doorStatus",t().doorWrong);
  return false;
 }
 $("doorCode").value=value;
 stopCamera();
 text("doorStatus",t().doorDetected);
 void lookupDoorCode(value);
 return true;
}
function readImageQR(canvas){
 const ctx=canvas.getContext("2d",{willReadFrequently:true});
 if(!ctx)return null;
 const image=ctx.getImageData(0,0,canvas.width,canvas.height);
 return globalThis.jsQR(image.data,canvas.width,canvas.height,{inversionAttempts:"attemptBoth"});
}
async function readFrame(source,canvas){
 const detector=getNativeDetector();
 if(detector){
  try{
   const results=await detector.detect(source);
   if(results?.length)return {data:results[0].rawValue};
  }catch(_){nativeDetector=false;}
 }
 return readImageQR(canvas);
}
function scanFrame(timestamp){
 if(!cameraStream)return;
 frameId=requestAnimationFrame(scanFrame);
 if(cameraBusy||timestamp-lastFrame<185)return;
 lastFrame=timestamp;
 const video=$("doorVideo");
 if(!video||video.readyState<2||!video.videoWidth||!video.videoHeight)return;
 cameraBusy=true;
 (async()=>{
  const w=Math.min(1000,video.videoWidth),h=Math.max(1,Math.round(video.videoHeight*w/video.videoWidth));
  const canvas=$("doorCanvas");
  canvas.width=w;canvas.height=h;
  const ctx=canvas.getContext("2d",{willReadFrequently:true});
  if(!ctx)throw Error("Canvas unavailable");
  ctx.drawImage(video,0,0,w,h);
  const result=await readFrame(video,canvas);
  if(!cameraStream)return;
  if(result?.data){scanCount=0;useReadResult(result.data);}
  else if(++scanCount===50){text("doorStatus",t().doorSearching);scanCount=0;}
 })().catch(()=>{
   // Do not silently stop scanning if an individual frame cannot be decoded.
   if(cameraStream)text("doorStatus",t().doorNoQr);
 }).finally(()=>{cameraBusy=false;});
}
function stopCamera(){
 if(frameId!==null){cancelAnimationFrame(frameId);frameId=null;}
 if(cameraStream){cameraStream.getTracks().forEach(tr=>tr.stop());cameraStream=null;}
 const v=$("doorVideo");if(v){v.pause();v.srcObject=null;v.hidden=true;}
 const button=$("doorCamera");if(button)button.disabled=false;
 cameraBusy=false;
}
async function openCamera(){
 if(cameraStream)return;
 try{
  if(!profile||!["puerta","admin"].includes(profile.role))return;
  if(!navigator.mediaDevices?.getUserMedia||!window.isSecureContext)throw Error("Camera unavailable");
  await loadJsQr();
  let stream;
  try{
