      return out({ok:true,code:redemptionCode});
    }
    if(path==="/v1/door/redemptions/validate"){
      if(!staff(actor))return error("Acceso reservado al personal",403);
      const code=String(body.code||"").trim().toUpperCase();
      if(!/^CNJ-[A-F0-9]{10}$/.test(code))return error("Código de canje inválido");
      const redemption=await env.DB.prepare("SELECT id,user_id,status FROM redemptions WHERE code=?").bind(code).first();
      if(!redemption||redemption.status!=="pendiente")return error("Canje no encontrado o ya validado",404);
      if(redemption.user_id===actor.id)return error("No puedes validar tu propio canje",403);
      const result=await env.DB.prepare(
        "UPDATE redemptions SET status='validado',validated_at=datetime('now'),validated_by=? "+
        "WHERE id=? AND status='pendiente' RETURNING id"
      ).bind(actor.id,redemption.id).first();
      if(!result)return error("Canje no encontrado o ya validado",409);
      return out({ok:true});
    }
    if(path==="/v1/admin/member"){
      if(!admin(actor))return error("Acceso reservado a administradores",403);
      if(!uuid(body.member_id))return error("Socio inválido");
      const target=await env.DB.prepare("SELECT id,name,role,points,lifetime_points,visits FROM profiles WHERE id=?").bind(body.member_id).first();
      if(!target)return error("La cuenta ya no existe",404);
      const name=String(body.name||"").trim(),role=String(body.role||""),
        reason=String(body.reason||"").trim();
      if(name.length<2||name.length>80||!["socio","puerta","admin"].includes(role)||reason.length<5||reason.length>250)
        return error("Nombre, rol o motivo no válidos");
      const points=Number(body.points),lifetime=Number(body.lifetime_points),visits=Number(body.visits);
      if(![points,lifetime,visits].every(Number.isSafeInteger)||points<0||points>100000000||
         lifetime<0||lifetime>100000000||visits<0||visits>1000000)
        return error("Puntos o visitas no válidos");
      const before={name:target.name,role:target.role,points:target.points,
        lifetime_points:target.lifetime_points,visits:target.visits};
      const after={name,role,points,lifetime_points:Math.max(lifetime,points),visits};
      // The trigger verifies admin rights, concurrency and the last-admin invariant
      // before applying the update and recording its audit log atomically.
      await env.DB.prepare(
        "INSERT INTO admin_member_changes(id,member_id,admin_id,before_data,after_data,reason) "+
        "VALUES (?,?,?,?,?,?)"
      ).bind(crypto.randomUUID(),target.id,actor.id,JSON.stringify(before),JSON.stringify(after),reason).run();
      return out({ok:true,profile:{id:target.id,...after}});
    }
    if(path==="/v1/admin/moments/create"){
      if(!admin(actor))return error("Acceso reservado a administradores",403);
      const title=String(body.title||"").trim(),date=String(body.event_date||"");
      if(title.length<2||title.length>120||!/^\d{4}-\d{2}-\d{2}$/.test(date))return error("Datos de la galería no válidos");
      const id=crypto.randomUUID();
      await env.DB.prepare("INSERT INTO moments_albums(id,title,event_date,published) VALUES (?,?,?,0)").bind(id,title,date).run();
      return out({ok:true,id});
    }
    if(path==="/v1/admin/moments/publish"){
      if(!admin(actor))return error("Acceso reservado a administradores",403);
      if(!uuid(body.album_id)||typeof body.published!=="boolean")return error("Galería inválida");
      const record=await env.DB.prepare("UPDATE moments_albums SET published=? WHERE id=? RETURNING id,published")
        .bind(body.published?1:0,body.album_id).first();
      return record?out({ok:true,published:!!record.published}):error("Galería no encontrada",404);
    }
    if(photoMatch){
      if(!admin(actor))return error("Acceso reservado a administradores",403);
      const album=await env.DB.prepare("SELECT id FROM moments_albums WHERE id=?").bind(photoMatch[1]).first();
      if(!album)return error("Galería no encontrada",404);
      const mime=(request.headers.get("Content-Type")||"").toLowerCase();
      if(!["image/jpeg","image/png","image/webp"].includes(mime))return error("El archivo debe ser JPG, PNG o WebP",415);
      const size=Number(request.headers.get("Content-Length")||0);
      if(size>8*1024*1024)return error("El tamaño máximo de una foto es 8 MB",413);
      const bytes=await request.arrayBuffer();
      if(bytes.byteLength===0||bytes.byteLength>8*1024*1024)return error("Tamaño de archivo no válido",413);
      const start=new Uint8Array(bytes.slice(0,12));
      const jpeg=mime==="image/jpeg"&&start[0]===0xff&&start[1]===0xd8;
      const png=mime==="image/png"&&start[0]===0x89&&start[1]===0x50&&start[2]===0x4e&&start[3]===0x47;
      const webp=mime==="image/webp"&&String.fromCharCode(...start.slice(0,4))==="RIFF"&&String.fromCharCode(...start.slice(8,12))==="WEBP";
      if(!jpeg&&!png&&!webp)return error("Formato de imagen incorrecto",415);
      const id=crypto.randomUUID(),ext=mime==="image/png"?"png":mime==="image/webp"?"webp":"jpg";
      const key="moments/"+album.id+"/"+id+"."+ext;
      await env.MEDIA.put(key,bytes,{httpMetadata:{contentType:mime}});
      try{
        await env.DB.prepare("INSERT INTO moments_photos(id,album_id,storage_path) VALUES (?,?,?)").bind(id,album.id,key).run();
      }catch(e){await env.MEDIA.delete(key);throw e;}
      return out({ok:true,id});
    }
  }catch(err){
    console.error("Staging operation:",String(err?.message||"error").slice(0,200));
    return error(errorMessage(err),409);
  }
  return error("Ruta no encontrada",404);
}

modules.suggestion-routes.js:
/* Bellaquitas Fest — buzón público de sugerencias para el espejo Cloudflare.
 * Activo ÚNICAMENTE si SUGGESTIONS_ENABLED=yes; independiente de
 * STAGING_MUTATIONS para no abrir puntos, visitas, permisos o panel.
 * Antiabuso: Turnstile validado en servidor, HMAC IP / límites D1.
 */
import {checkOrigin} from "./auth-routes.js";
const HEAD={"Cache-Control":"no-store","Content-Type":"application/json; charset=utf-8",
 "X-Content-Type-Options":"nosniff","X-Robots-Tag":"noindex,nofollow",
 "Referrer-Policy":"no-referrer"};
const reply=(body,status=200)=>new Response(JSON.stringify(body),{status,headers:HEAD});
const enabled=env=>env.SUGGESTIONS_ENABLED==="yes"&&env.DB&&
 typeof env.EMAIL_RATE_KEY==="string"&&env.EMAIL_RATE_KEY.length>=32&&
 typeof env.TURNSTILE_SECRET==="string"&&env.TURNSTILE_SECRET.length>8&&
 typeof env.TURNSTILE_SITE_KEY==="string"&&env.TURNSTILE_SITE_KEY.length>8;
async function readBody(request){
 if(!/^application\/json(?:;|$)/i.test(request.headers.get("Content-Type")||""))
  throw Error("Se requiere JSON");
 const n=Number(request.headers.get("Content-Length")||0);
 if(n>4400)throw Error("Mensaje demasiado grande");
 const raw=await request.text();
 if(raw.length>4400)throw Error("Mensaje demasiado grande");
 const data=JSON.parse(raw);
 if(!data||typeof data!=="object"||Array.isArray(data))throw Error("Mensaje inválido");
 return data;
}
async function hmacKey(env,request){
 const ip=request.headers.get("CF-Connecting-IP")||"unknown";
 const key=await crypto.subtle.importKey("raw",new TextEncoder().encode(env.EMAIL_RATE_KEY),
  {name:"HMAC",hash:"SHA-256"},false,["sign"]);
 const signed=new Uint8Array(await crypto.subtle.sign("HMAC",key,
  new TextEncoder().encode("suggestions:v1:ip:"+ip)));
 return btoa(String.fromCharCode(...signed)).replace(/\+/g,"-").replace(/\//g,"_").replace(/=+$/,"");
}
async function verifyTurnstile(env,request,token){
 if(typeof token!=="string"||token.length<10||token.length>2048)return false;
 const params=new URLSearchParams({secret:env.TURNSTILE_SECRET,response:token});
 const ip=request.headers.get("CF-Connecting-IP");if(ip)params.set("remoteip",ip);
 try{
  const r=await fetch("https://challenges.cloudflare.com/turnstile/v0/siteverify",
   {method:"POST",body:params});
  if(!r.ok)return false;
  const json=await r.json();
  const host=env.TURNSTILE_EXPECTED_HOSTNAME||new URL(env.PUBLIC_ORIGIN).hostname;
  return json.success===true&&json.hostname===host;
 }catch{return false;}
}
async function quota(env,key){
 const result=await env.DB.prepare(
  "INSERT INTO auth_email_rate_limits(key_hash,attempts,expires_at) "+
  "VALUES (?,1,unixepoch()+3600) "+
  "ON CONFLICT(key_hash) DO UPDATE SET "+
  "attempts=CASE WHEN expires_at<=unixepoch() THEN 1 ELSE attempts+1 END, "+
  "expires_at=CASE WHEN expires_at<=unixepoch() THEN unixepoch()+3600 ELSE expires_at END "+
  "RETURNING attempts,MAX(1,expires_at-unixepoch()) AS retry_seconds"
 ).bind(key).first();
 return {allowed:!!result&&Number(result.attempts)<=5,retry:Number(result?.retry_seconds)||3600};
}
export async function suggestionRoute(request,env){
 const path=new URL(request.url).pathname;
 if(path!=="/v1/mirror/public/suggestions/status"&&
    path!=="/v1/mirror/public/suggestions")return null;
 if(path.endsWith("/status")){
  if(request.method!=="GET")return reply({error:"Método no permitido"},405);
  return reply({enabled:!!enabled(env),turnstileSiteKey:enabled(env)?env.TURNSTILE_SITE_KEY:null});
 }
 if(request.method!=="POST")return reply({error:"Método no permitido"},405);
 if(!checkOrigin(request,env))return reply({error:"Origen no autorizado"},403);
 if(!enabled(env))return reply({error:"El buzón todavía no está activado en esta copia"},423);
 let body;
 try{body=await readBody(request);}
 catch{return reply({error:"Datos del mensaje inválidos"},400);}
 const name=typeof body.name==="string"?body.name.trim():"";
 const message=typeof body.message==="string"?body.message.trim():"";
 if(name.length>80||message.length<5||message.length>2000)
  return reply({error:"Escribe un mensaje de entre 5 y 2000 caracteres"},400);
 // Campo oculto contra bots de formulario, nunca se persiste ni se muestra.
 if(body.website)return reply({ok:true});
 const key=await hmacKey(env,request);
 const blocked=await env.DB.prepare(
  "SELECT attempts,MAX(0,expires_at-unixepoch()) AS retry FROM auth_email_rate_limits "+
  "WHERE key_hash=?"
 ).bind(key).first();
 if(blocked&&Number(blocked.attempts)>=5&&Number(blocked.retry)>0)
  return reply({error:"Demasiados mensajes. Inténtalo más tarde.",retry_seconds:blocked.retry},429);
 if(!await verifyTurnstile(env,request,body.turnstileToken))
  return reply({error:"Completa la comprobación de seguridad para enviar la sugerencia"},403);
 const rate=await quota(env,key);
 if(!rate.allowed)return reply({error:"Demasiados mensajes. Inténtalo más tarde.",retry_seconds:rate.retry},429);
 try{
  await env.DB.prepare(
   "INSERT INTO community_suggestions(id,name,message,status) VALUES (?,?,?,'nuevo')"
  ).bind(crypto.randomUUID(),name,message).run();
  return reply({ok:true,message:"Sugerencia enviada. Gracias."},201);
 }catch(error){
  console.error("Suggestion submit:",String(error?.message||"error").slice(0,105));
  return reply({error:"No se pudo guardar tu sugerencia"},503);
 }
}

