export const MIRROR_SUGGESTIONS_UI="/* Reutiliza el formulario de sugerencias del diseño original.
   Solo añade Turnstile y llama al Worker Cloudflare con cuota antispam.
   No envía el texto a terceros salvo la comprobación de CAPTCHA. */
(()=>{
"use strict";
const $=s=>document.querySelector(s);
const copy={
 es:{need:"Completa la comprobación de seguridad para enviar la sugerencia.",
  unavailable:"El buzón de pruebas todavía no está disponible.",
  send:"Enviando sugerencia…",ok:"¡Gracias! 💌 Tu sugerencia se ha enviado correctamente.",
  error:"No se pudo enviar tu sugerencia. Comprueba los datos y vuelve a intentarlo.",
  invalid:"Escribe una sugerencia de entre 5 y 2000 caracteres."},
 fr:{need:"Terminez la vérification de sécurité pour envoyer votre suggestion.",
  unavailable:"Le formulaire de suggestions n'est pas encore disponible en test.",
  send:"Envoi de votre suggestion…",ok:"Merci ! 💌 Votre suggestion a bien été envoyée.",
  error:"Impossible d'envoyer votre suggestion. Réessayez.",
  invalid:"Écrivez une suggestion de 5 à 2 000 caractères."}
};
const t=()=>copy[document.documentElement.lang==="fr"?"fr":"es"];
const statusPromise=fetch("/v1/mirror/public/suggestions/status",{
 credentials:"same-origin",cache:"no-store"
}).then(r=>r.ok?r.json():null).catch(()=>null);
let attached=null,widget=null,rendering=false;
function feedback(form,message){
 const box=form?.querySelector("#suggestion-feedback");
 if(box)box.textContent=message;
}
function clear(){
 if(widget!==null&&window.turnstile){
  try{window.turnstile.remove(widget);}catch{}
 }
