}
async function ensure(){
 const form=$("#community-suggestion-form");
 if(!form){if(attached)clear();return;}
 if(form===attached&&widget!==null)return;
 if(attached!==form)clear();
 attached=form;
 const status=await statusPromise;
 if(!form.isConnected||attached!==form)return;
 if(!status?.enabled||!status.turnstileSiteKey){
  feedback(form,t().unavailable);
  return;
 }
 if(!window.turnstile||rendering)return;
 rendering=true;
 try{
  let slot=form.querySelector("#bq-suggestions-turnstile");
  if(!slot){
   slot=document.createElement("div");
   slot.id="bq-suggestions-turnstile";
   slot.style.cssText="display:flex;justify-content:center;align-items:center;min-height:68px;margin:10px 0";
   form.querySelector('button[type="submit"]')?.before(slot);
  }
  widget=window.turnstile.render(slot,{
   sitekey:status.turnstileSiteKey,theme:"dark",
   "expired-callback":()=>feedback(form,t().need),
   "error-callback":()=>feedback(form,t().need)
  });
 }catch{feedback(form,t().unavailable);}
 finally{rendering=false;}
}
async function send(form){
 const button=form.querySelector('button[type="submit"]');
 if(!button||button.disabled)return;
 const fd=new FormData(form);
 const name=String(fd.get("name")||"").trim();
 const message=String(fd.get("message")||"").trim();
 if(name.length>80||message.length<5||message.length>2000){feedback(form,t().invalid);return;}
 const status=await statusPromise;
 if(!form.isConnected)return;
 if(!status?.enabled){feedback(form,t().unavailable);return;}
 const token=widget!==null&&window.turnstile?window.turnstile.getResponse(widget):"";
 if(!token){feedback(form,t().need);return;}
 button.disabled=true;const before=button.textContent;
