  const response=await fetch("/v1/mirror/public/suggestions",{
   method:"POST",credentials:"same-origin",cache:"no-store",
   headers:{"Content-Type":"application/json"},
   body:JSON.stringify({name,message,website:String(fd.get("website")||""),
     turnstileToken:token})
  });
  const result=await response.json().catch(()=>({}));
  if(!response.ok)throw Error(result.error||t().error);
  form.reset();feedback(form,t().ok);
 }catch(e){feedback(form,e.message||t().error);}
 finally{
  if(widget!==null&&window.turnstile){
   try{window.turnstile.reset(widget);}catch{}
  }
  if(button.isConnected){button.disabled=false;button.textContent=before;}
 }
}
document.addEventListener("submit",event=>{
 if(event.target?.id!=="community-suggestion-form")return;
 event.preventDefault();event.stopImmediatePropagation();
