  const hash=await digest(secret);
  return env.DB.prepare(
    "SELECT p.id,p.name,p.role,p.member_code,p.points,p.lifetime_points,p.visits,p.created_at "+
    "FROM auth_sessions s JOIN profiles p ON p.id=s.profile_id "+
